flowchart TD     Start["Start: Source=0"] --&gt; Init["dist[0]=0, others=∞"]     Init --&gt; PQ["Min-Heap: (0,0)"]     PQ --&gt; Extract["Extract Min: u"]     Extract --&gt; Relax{"Relax edges from u"}     Relax -- Update --&gt; Update["Update dist[v], decrease-key in heap"]     Update --&gt; Extract     Extract --&gt; Done{"Heap Empty?"}     Done -- No --&gt; Extract     Done -- Yes --&gt; Result["Shortest Paths"]      style Start fill:#e8f5e9,stroke:#2e7d32     style Result fill:#e8f5e9,stroke:#2e7d32,stroke-width:2px <pre><code>// dijkstra_demo.c - Dijkstra's Shortest Path
#include &lt;stdio.h&gt;
#include &lt;stdlib.h&gt;
#include &lt;limits.h&gt;
#define MAXV 100
#define INF INT_MAX

typedef struct node {
    int vertex, weight;
    struct node *next;
} node_t;

node_t *adj[MAXV];

// Min-heap for Dijkstra
typedef struct {
    int v[MAXV], dist[MAXV], pos[MAXV];
    int n;
} MinHeap;

void swap_h(MinHeap *h, int i, int j) {
    int tv = h-&gt;v[i], td = h-&gt;dist[i];
    h-&gt;v[i] = h-&gt;v[j]; h-&gt;dist[i] = h-&gt;dist[j]; h-&gt;pos[h-&gt;v[i]] = i;
    h-&gt;v[j] = tv; h-&gt;dist[j] = td; h-&gt;pos[h-&gt;v[j]] = j;
}

void heapify_up(MinHeap *h, int i) {
    while (i &gt; 1 &amp;&amp; h-&gt;dist[i] &lt; h-&gt;dist[i/2]) swap_h(h, i, i/2), i /= 2;
}

void heapify_down(MinHeap *h, int i) {
    int smallest = i, l = 2*i, r = 2*i+1;
    if (l &lt;= h-&gt;n &amp;&amp; h-&gt;dist[l] &lt; h-&gt;dist[smallest]) smallest = l;
    if (r &lt;= h-&gt;n &amp;&amp; h-&gt;dist[r] &lt; h-&gt;dist[smallest]) smallest = r;
    if (smallest != i) { swap_h(h, i, smallest); heapify_down(h, smallest); }
}

void add_edge(int u, int v, int w) {
    node_t *n = malloc(sizeof(node_t));
    n-&gt;vertex = v; n-&gt;weight = w; n-&gt;next = adj[u]; adj[u] = n;
}

void dijkstra(int V, int src) {
    int dist[MAXV];
    for (int i = 0; i &lt; V; i++) dist[i] = INF;
    dist[src] = 0;

    MinHeap h = {{0}, {0}, {0}, 0};
    for (int i = 0; i &lt; V; i++) {
        h.v[++h.n] = i;
        h.dist[h.n] = dist[i];
        h.pos[i] = h.n;
    }
    for (int i = h.n/2; i &gt;= 1; i--) {
        int smallest = i, l = 2*i, r = 2*i+1;
        if (l &lt;= h.n &amp;&amp; h.dist[l] &lt; h.dist[smallest]) smallest = l;
        if (r &lt;= h.n &amp;&amp; h.dist[r] &lt; h.dist[smallest]) smallest = r;
        if (smallest != i) { swap_h(&amp;h, i, smallest); heapify_down(&amp;h, i); }
    }

    while (h.n &gt; 0) {
        int u = h.v[1];
        int du = h.dist[1];
        h.v[1] = h.v[h.n];
        h.dist[1] = h.dist[h.n];
        h.pos[h.v[1]] = 1;
        h.n--;
        heapify_down(&amp;h, 1);

        if (du == INF) break;

        for (node_t *p = adj[u]; p; p = p-&gt;next) {
            int v = p-&gt;vertex, w = p-&gt;weight;
            if (dist[u] + w &lt; dist[v]) {
                dist[v] = dist[u] + w;
                int idx = h.pos[v];
                h.dist[idx] = dist[v];
                heapify_up(&amp;h, idx);
            }
        }
    }

    printf("Shortest distances from %d:\n", src);
    for (int i = 0; i &lt; V; i++)
        printf("  to %d: %d\n", i, dist[i] == INF ? -1 : dist[i]);
}

int main() {
    // Graph with weights
    add_edge(0, 1, 4); add_edge(0, 2, 2);
    add_edge(1, 2, 1); add_edge(1, 3, 5);
    add_edge(2, 3, 8); add_edge(2, 4, 10);
    add_edge(3, 4, 2); add_edge(3, 5, 6);
    add_edge(4, 5, 2);

    printf("=== Dijkstra's Shortest Path ===\n");
    dijkstra(6, 0);

    return 0;
}
